<template><div class="app-container"><div class="head"><h2>线下巡店任务</h2><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="dialog=true">创建任务</el-button></div></div>
<el-table :data="items" border><el-table-column prop="taskCode" label="任务编号"/><el-table-column prop="title" label="任务"/><el-table-column prop="storeName" label="门店"/><el-table-column prop="assigneeId" label="执行人"/><el-table-column prop="plannedStartTime" label="计划开始"/><el-table-column prop="plannedEndTime" label="计划结束"/><el-table-column prop="status" label="状态"/><el-table-column prop="checkinDistanceMeters" label="签到距离"/><el-table-column label="操作"><template slot-scope="{row}"><el-button size="mini" @click="detail(row)">检查结果</el-button></template></el-table-column></el-table>
<el-dialog title="创建巡店任务" :visible.sync="dialog"><el-form label-width="90px"><el-form-item label="任务名称"><el-input v-model="form.title"/></el-form-item><el-form-item label="门店编号"><el-input v-model="form.storeId"/></el-form-item><el-form-item label="门店名称"><el-input v-model="form.storeName"/></el-form-item><el-form-item label="执行人ID"><el-input-number v-model="form.assigneeId"/></el-form-item><el-form-item label="计划时间"><el-date-picker v-model="range" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss"/></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">派发</el-button></span></el-dialog>
<el-dialog title="检查结果" :visible.sync="detailDialog" width="75%"><el-table :data="details"><el-table-column prop="itemGroup" label="分组"/><el-table-column prop="itemName" label="检查项"/><el-table-column prop="result" label="结果"/><el-table-column prop="severity" label="等级"/><el-table-column prop="note" label="备注"/><el-table-column prop="evidenceUrls" label="证据"/></el-table></el-dialog></div></template>
<script>import{ storeVisits, createStoreVisit, visitCheckResults }from'@/api/inspection';const d=v => (v&&v.data)||v||[];export default{ name:'StoreVisitManagement', data:() => ({ items:[], details:[], dialog:false, detailDialog:false, range:[], form:{} }), created(){this.load()}, methods:{ async load(){this.items=d(await storeVisits())}, async create(){this.form.plannedStartTime=this.range[0];this.form.plannedEndTime=this.range[1];await createStoreVisit(this.form);this.dialog=false;this.form={};this.range=[];this.load()}, async detail(r){this.details=d(await visitCheckResults(r.id));this.detailDialog=true} } }</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.head h2{margin:0}</style>
